1	import { z } from "zod";
2	import { baselineFrameBudgets, moveTimingSchema, type MoveTiming } from "../frameBudgets.js";
3	import { formatIssues, type ValidationResult } from "../rules.js";
4	
5	/**
6	 * An axis-aligned box in integer sub-pixels, relative to a fighter's origin (the middle of its feet) for a fighter
7	 * facing right; y grows upwards from the floor. The box covers the half-open ranges [x, x + w) × [y, y + h), so it
8	 * needs a positive width and height to cover anything.
9	 */
10	export const boxSchema = z.strictObject({
11	  x: z.int(),
12	  y: z.int(),
13	  w: z.int().positive(),
14	  h: z.int().positive(),
15	});
16	
17	export type Box = z.infer<typeof boxSchema>;
18	
19	const count = z.int().nonnegative();
20	const positive = z.int().positive();
21	
22	/**
23	 * §8's move timing, restricted to what a fighter's own move can be: numeric active frames, blockable or not. The
24	 * rows go through §8's own schema, so its rules (positive startup and active frames, block advantage within
25	 * active + recovery) are checked in one place.
26	 */
27	export const duelMoveTimingSchema = moveTimingSchema.transform((timing, ctx) => {
28	  const { active, onBlock } = timing;
29	  if (active === "projectile-life") {
30	    ctx.issues.push({ code: "custom", input: active, path: ["active"], message: "a fighter's move needs a number of active frames" });
31	    return z.NEVER;
32	  }
33	  if (onBlock.kind === "spacing-dependent") {
34	    ctx.issues.push({ code: "custom", input: onBlock, path: ["onBlock"], message: "a fighter's move is blockable with a frame advantage, or unguardable" });
35	    return z.NEVER;
36	  }
37	  return { ...timing, active, onBlock };
38	});
39	
40	export type DuelMoveTiming = z.infer<typeof duelMoveTimingSchema>;
41	
42	export const guardLevelSchema = z.enum(["high", "mid", "low", "unguardable"]);
43	export type GuardLevel = z.infer<typeof guardLevelSchema>;
44	
45	export const moveCategorySchema = z.enum(["light", "heavy", "special", "throw"]);
46	export type MoveCategory = z.infer<typeof moveCategorySchema>;
47	
48	/**
49	 * One move. Frame counts are 60 Hz frames: `startup` frames come before the first active frame, then `active`, then
50	 * `recovery`. Distances and velocities are sub-pixels (per frame).
51	 */
52	export const duelMoveSchema = z
53	  .strictObject({
54	    timing: duelMoveTimingSchema,
55	    kind: z.enum(["strike", "throw"]),
56	    /** Decides what blocking it costs (§7) and which rules apply. */
57	    category: moveCategorySchema,
58	    /** The hurtbox the attacker uses while performing the move. */
59	    stance: z.enum(["standing", "crouching"]),
60	    guard: guardLevelSchema,
61	    /** One box for the whole active phase. */
62	    hitbox: boxSchema,
63	    /** Before combo scaling. */
64	    damage: positive,
65	    /** Frames the defender cannot act after a hit, counting the contact frame; for a throw, the knockdown after it. */
66	    hitstun: positive,
67	    /** Frames the defender cannot act after blocking, counting the contact frame; 0 for a throw. */
68	    blockstun: count,
69	    hitPushback: count,
70	    blockPushback: count,
71	    /** Upward velocity given to the defender on hit (sub-pixels per frame); 0 leaves a grounded defender grounded. */
72	    launch: count,
73	    /** Forward velocity of the attacker during startup and active frames. */
74	    advance: count,
75	    /** Frames from the move's first frame during which strikes pass through the attacker. */
76	    strikeInvulnerable: count,
77	    /** Stamina the defender spends to block it. */
78	    guardStaminaCost: count,
79	  })
80	  .superRefine((move, ctx) => {
81	    const { timing } = move;
82	    const isThrow = move.kind === "throw";
83	    if (isThrow !== (move.category === "throw") || isThrow !== (move.guard === "unguardable")) {
84	      ctx.addIssue({ code: "custom", path: ["kind"], message: "a throw, and only a throw, has the throw category and is unguardable" });
85	    }
86	    if (isThrow) {
87	      if (timing.onBlock.kind !== "unguardable") ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a throw is unguardable" });
88	      if (move.blockstun !== 0) ctx.addIssue({ code: "custom", path: ["blockstun"], message: "a throw cannot be blocked" });
89	    } else if (timing.onBlock.kind !== "frames") {
90	      ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a strike needs a frame advantage on block" });
91	    } else if (move.blockstun !== timing.active + timing.recovery + timing.onBlock.advantage) {
92	      // Contact on the first active frame, which is also the defender's first blockstun frame.
93	      ctx.addIssue({
94	        code: "custom",
95	        path: ["blockstun"],
96	        message: `blockstun ${move.blockstun} does not give ${timing.onBlock.advantage} on block (needs ${timing.active + timing.recovery + timing.onBlock.advantage})`,
97	      });
98	    }
99	    if (move.strikeInvulnerable > timing.startup) {
100	      ctx.addIssue({ code: "custom", path: ["strikeInvulnerable"], message: "strike invulnerability cannot outlast startup" });
101	    }
102	  });
103	
104	export type DuelMove = z.infer<typeof duelMoveSchema>;
105	
106	const hurtboxesSchema = z.strictObject({ standing: boxSchema, crouching: boxSchema, airborne: boxSchema });
107	
108	/** A fighter's body and movement. Distances are sub-pixels, speeds sub-pixels per frame, durations frames. */
109	export const duelFighterSchema = z.strictObject({
110	  hurtboxes: hurtboxesSchema,
111	  /** Two fighters' pushboxes never overlap: centred on the origin, `halfWidth` either side, `height` tall. */
112	  pushbox: z.strictObject({ halfWidth: positive, height: positive }),
113	  walkForwardSpeed: positive,
114	  walkBackSpeed: positive,
115	  jumpVelocity: positive,
116	  jumpSpeedX: count,
117	  /** Subtracted from the vertical velocity every airborne frame. */
118	  gravity: positive,
119	  dashFrames: positive,
120	  dashSpeed: positive,
121	  backdashFrames: positive,
122	  backdashSpeed: positive,
123	  /** Recovery of both fighters after a throw escape or two throws breaking each other. */
124	  throwBreakFrames: positive,
125	  /** How far each fighter is pushed away from the other when a throw breaks. */
126	  throwBreakPushback: count,
127	});
128	
129	export type DuelFighter = z.infer<typeof duelFighterSchema>;
130	
131	/** The single-plane arena: a floor between two walls. */
132	export const duelArenaSchema = z.strictObject({
133	  subPixelsPerPixel: positive,
134	  /** Wall to wall, in sub-pixels. Fighters' origins stay a pushbox half-width inside the walls. */
135	  width: positive,
136	  /** Distance between the two fighters' origins at the start, placed symmetrically about the centre. */
137	  startGap: positive,
138	});
139	
140	export type DuelArena = z.infer<typeof duelArenaSchema>;
141	
142	/** §7's round, stamina and combo rules as numbers. */
143	export const duelRulesSchema = z.strictObject({
144	  roundFrames: positive,
145	  overtimeFrames: positive,
146	  maxHealth: positive,
147	  maxStamina: positive,
148	  dashStaminaCost: count,
149	  guardStaminaCost: z.strictObject({ light: count, heavy: count, special: count }),
150	  /** Frames without spending or blocking before stamina regenerates. */
151	  staminaRegenDelayFrames: count,
152	  /** After the delay, one stamina point every this many frames (3 frames is 20 a second). */
153	  staminaRegenIntervalFrames: positive,
154	  guardBreakStaggerFrames: positive,
155	  /** Added to the stamina a guard break leaves, up to `maxStamina`. */
156	  guardBreakStaminaRestore: count,
157	  /** Percent of base damage for the first, second, ... damaging hit of a combo. */
158	  comboScaling: z.array(z.int().min(1).max(100)).min(1).readonly(),
159	  /** The damaging hit that forces the non-juggleable recovery. */
160	  comboCap: positive,
161	  forcedRecoveryFrames: positive,
162	  throwEscapeFrames: positive,
163	  inputBufferFrames: positive,
164	  /**
165	   * The throw chord window: a light or heavy move that a free fighter started becomes the throw when the other button
166	   * is pressed up to this many frames later, before the move's first active frame (keyboard rollover, §8).
167	   */
168	  throwChordFrames: count,
169	});
170	
171	export type DuelRules = z.infer<typeof duelRulesSchema>;
172	
173	/** Which move each input starts (§8): down + heavy is the low sweep, forward + heavy the launcher, down + light the anti-air. */
174	export const duelCommandsSchema = z.strictObject({
175	  light: z.string(),
176	  downLight: z.string(),
177	  heavy: z.string(),
178	  downHeavy: z.string(),
179	  forwardHeavy: z.string(),
180	  special1: z.string(),
181	  special2: z.string(),
182	  throw: z.string(),
183	});
184	
185	export type DuelCommands = z.infer<typeof duelCommandsSchema>;
186	
187	/**
188	 * The commands a light or heavy press starts, each with the button that still turns it into the throw inside the
189	 * throw chord window.
190	 */
191	export const THROW_CHORD_PARTNER = {
192	  light: "heavy",
193	  downLight: "heavy",
194	  heavy: "light",
195	  downHeavy: "light",
196	  forwardHeavy: "light",
197	} as const satisfies Partial<Record<keyof DuelCommands, "light" | "heavy">>;
198	
199	/** Everything the duel step reads. `movesetVersion` identifies it all, and a duel state records that version. */
200	export const duelMovesetSchema = z
201	  .strictObject({
202	    rules: duelRulesSchema,
203	    arena: duelArenaSchema,
204	    fighter: duelFighterSchema,
205	    moves: z.array(duelMoveSchema).min(1).readonly(),
206	    commands: duelCommandsSchema,
207	  })
208	  .superRefine((moveset, ctx) => {
209	    const { rules, arena, fighter } = moveset;
210	    const byId = new Map<string, DuelMove>();
211	    moveset.moves.forEach((move, index) => {
212	      const id = move.timing.id;
213	      if (byId.has(id)) ctx.addIssue({ code: "custom", path: ["moves", index, "timing", "id"], message: `${id}: duplicate move id` });
214	      byId.set(id, move);
215	      // A move named like a §8 baseline row must use that row's timing exactly.
216	      const baseline = baselineFrameBudgets.find((row) => row.id === id);
217	      if (baseline !== undefined && !sameTiming(move.timing, baseline)) {
218	        ctx.addIssue({ code: "custom", path: ["moves", index, "timing"], message: `${id}: timing differs from §8's baseline row` });
219	      }
220	      const cost = move.category === "throw" ? 0 : rules.guardStaminaCost[move.category];
221	      if (move.guardStaminaCost !== cost) {
222	        ctx.addIssue({ code: "custom", path: ["moves", index, "guardStaminaCost"], message: `${id}: blocking a ${move.category} costs ${cost}` });
223	      }
224	    });
225	    for (const [command, id] of Object.entries(moveset.commands)) {
226	      const move = byId.get(id);
227	      if (move === undefined) {
228	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `unknown move "${id}"` });
229	      } else if ((command === "throw") !== (move.kind === "throw")) {
230	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `"${id}" is the wrong kind of move for ${command}` });
231	      }
232	    }
233	    // The chord window closes before a light or heavy move could strike, so a throw never replaces an active hitbox.
234	    for (const command of Object.keys(THROW_CHORD_PARTNER) as (keyof typeof THROW_CHORD_PARTNER)[]) {
235	      const move = byId.get(moveset.commands[command]);
236	      if (move !== undefined && rules.throwChordFrames >= move.timing.startup) {
237	        ctx.addIssue({ code: "custom", path: ["rules", "throwChordFrames"], message: `the throw chord window outlasts ${move.timing.id}'s startup` });
238	      }
239	    }
240	    if (rules.comboCap > rules.comboScaling.length) {
241	      ctx.addIssue({ code: "custom", path: ["rules", "comboCap"], message: "every hit up to the cap needs a scaling step" });
242	    }
243	    if (rules.dashStaminaCost > rules.maxStamina) {
244	      ctx.addIssue({ code: "custom", path: ["rules", "dashStaminaCost"], message: "a dash would cost more than full stamina" });
245	    }
246	    // Symmetric start positions need even distances, and both fighters must start inside the walls and out of reach
247	    // of every move, including the distance an advancing move travels through its startup and active frames (§6: no
248	    // free opening hit).
249	    if (arena.width % 2 !== 0 || arena.startGap % 2 !== 0) {
250	      ctx.addIssue({ code: "custom", path: ["arena"], message: "arena width and start gap must be even" });
251	    }
252	    if (arena.startGap > arena.width - 2 * fighter.pushbox.halfWidth) {
253	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "the start positions lie outside the walls" });
254	    }
255	    const hurtReach = Math.max(...Object.values(fighter.hurtboxes).map((box) => Math.max(box.x + box.w, -box.x)));
256	    const hitReach = Math.max(
257	      ...moveset.moves.map((move) => move.hitbox.x + move.hitbox.w + move.advance * (move.timing.startup + move.timing.active)),
258	    );
259	    if (arena.startGap < hitReach + hurtReach) {
260	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "fighters would start within reach of a move" });
261	    }
262	  });
263	
264	export type DuelMoveset = z.infer<typeof duelMovesetSchema>;
265	
266	function sameTiming(a: DuelMoveTiming, b: MoveTiming): boolean {
267	  const advantage = (timing: MoveTiming | DuelMoveTiming) => (timing.onBlock.kind === "frames" ? timing.onBlock.advantage : null);
268	  return (
269	    a.id === b.id &&
270	    a.name === b.name &&
271	    a.startup === b.startup &&
272	    a.active === b.active &&
273	    a.recovery === b.recovery &&
274	    a.onBlock.kind === b.onBlock.kind &&
275	    advantage(a) === advantage(b)
276	  );
277	}
278	
279	export function validateDuelMove(candidate: unknown): ValidationResult<DuelMove> {
280	  const parsed = duelMoveSchema.safeParse(candidate);
281	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
282	}
283	
284	export function validateDuelMoveset(candidate: unknown): ValidationResult<DuelMoveset> {
285	  const parsed = duelMovesetSchema.safeParse(candidate);
286	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
287	}
