25	/** Inputs one message carries at most: the newest frame and the three before it. */
26	export const MAX_DUEL_INPUTS_PER_MESSAGE = 4;
27	/** Clients send input messages at most this often (every second frame), half the gate's cap. */
28	export const DUEL_INPUT_MESSAGES_PER_SECOND = 30;
29	/** The server sends one frame bundle every this many frames (20 a second)... */
