33	/** The countdown before the fight, in frames (§6: three seconds). */
34	export const DUEL_COUNTDOWN_FRAMES = 180;
35	/** A player absent this long forfeits (§12); they may rejoin the same duel until then. */
36	export const DUEL_RECONNECT_SECONDS = 10;
