63	 * sequence number above the last accepted one, and a newest frame at most MAX_INPUT_LEAD_FRAMES past the server's.
64	 * The server's frame is negative during the countdown (frames left until the fight's frame 0).
65	 */
66	export function validateDuelInputMessage(message: unknown, context: InputContext): DuelInputValidation {
67	  const size = encodedSize(message);
68	  if (size === undefined) return { ok: false, reason: "malformed" };
69	  if (size > MAX_INPUT_MESSAGE_BYTES) return { ok: false, reason: "oversized" };
70	  const parsed = duelInputMessageSchema.safeParse(message);
