1	import { DUEL_BUTTONS, DUEL_INPUT_MASK, movesetVersion, type DuelMoveset } from "@pirate-sea-race/content/moves";
2	import { canonicalize } from "../hash.js";
3	import type {
4	  DuelConfig,
5	  DuelEvent,
6	  DuelEventKind,
7	  DuelPhase,
8	  DuelResult,
9	  DuelState,
10	  FighterAction,
11	  FighterState,
12	  InputBuffer,
13	} from "./state.js";
14	
15	/** A duel state as plain JSON-safe data: what the netcode stores and what the server sends as a checkpoint. */
16	export type DuelSnapshot = DuelState;
17	
18	/** A deep, independent copy of the complete duel state (it also proves every number is a safe integer). */
19	export function snapshotDuel(state: DuelState): DuelSnapshot {
20	  return JSON.parse(canonicalize(state)) as DuelSnapshot;
21	}
22	
23	/**
24	 * Turns a snapshot (possibly received over the wire) back into a state to step from. It is refused when it was
25	 * taken on other move data, or when any field is not what a duel state on this moveset can hold: a missing or extra
26	 * field, a wrong type, an integer out of range or an unknown move.
27	 */
28	export function restoreDuel(config: DuelConfig, snapshot: unknown): DuelState {
29	  if (typeof snapshot !== "object" || snapshot === null) throw new TypeError("a duel snapshot must be an object");
30	  const version = movesetVersion(config.moveset);
31	  const candidate = snapshot as Partial<DuelState>;
32	  if (candidate.movesetVersion !== version) {
33	    throw new Error(`the snapshot was taken on moveset ${String(candidate.movesetVersion)}, not ${version}`);
34	  }
35	  const issue = duelStateCheck(config.moveset)(snapshot, "");
36	  if (issue !== null) throw new TypeError(`the snapshot is not a duel state: ${issue}`);
37	  return snapshotDuel(candidate as DuelState);
38	}
39	
40	/** What is wrong with `value` at `path`, or null when nothing is. */
41	type Check = (value: unknown, path: string) => string | null;
42	
43	const at = (path: string, key: string | number) => (path === "" ? String(key) : `${path}.${key}`);
44	
45	const integer =
46	  (min: number, max = Number.MAX_SAFE_INTEGER): Check =>
47	  (value, path) =>
48	    Number.isSafeInteger(value) && (value as number) >= min && (value as number) <= max ? null : `${path} must be an integer from ${min} to ${max}`;
49	
50	const anyInteger: Check = (value, path) => (Number.isSafeInteger(value) ? null : `${path} must be a safe integer`);
51	
52	const boolean: Check = (value, path) => (typeof value === "boolean" ? null : `${path} must be a boolean`);
53	
54	const oneOf =
55	  (...values: readonly unknown[]): Check =>
56	  (value, path) =>
57	    values.includes(value) ? null : `${path} must be one of ${values.map((item) => JSON.stringify(item)).join(", ")}`;
58	
59	/** One of a string union, listed as a record so that the compiler notices a member missing from the list. */
60	const member = <T extends string>(members: Record<T, true>): Check => oneOf(...Object.keys(members));
61	
62	const nullable =
63	  (check: Check): Check =>
64	  (value, path) =>
65	    value === null ? null : check(value, path);
66	
67	/** A plain object with exactly the listed fields; the mapped type makes the list cover every field of `T`. */
68	function exactly<T>(fields: { readonly [K in keyof T]-?: Check }): Check {
69	  const shape = fields as Readonly<Record<string, Check>>;
70	  return (value, path) => {
71	    if (typeof value !== "object" || value === null || Array.isArray(value)) return `${path || "the snapshot"} must be an object`;
72	    const extra = Object.keys(value).find((key) => !Object.hasOwn(shape, key));
73	    if (extra !== undefined) return `${at(path, extra)} is not a field`;
74	    for (const [key, check] of Object.entries(shape)) {
75	      const issue = check((value as Record<string, unknown>)[key], at(path, key));
76	      if (issue !== null) return issue;
77	    }
78	    return null;
79	  };
