58	export function stepDuel(config: DuelConfig, state: DuelState, inputs: DuelInputs): DuelState {
59	  const { moveset } = config;
60	  const version = movesetVersion(moveset);
61	  if (state.movesetVersion !== version) {
62	    throw new Error(`the duel runs on moveset ${state.movesetVersion}, not ${version}`);
63	  }
64	  const frame = state.frame + 1;
65	  if (state.result !== null) return { ...state, frame, events: [] };
66	
67	  const fighters = state.fighters;
68	  const input: Pair<FrameInput> = [readInput(moveset, fighters[0], inputs[0]), readInput(moveset, fighters[1], inputs[1])];
69	
70	  // 2. Detection, each against the same start-of-frame state.
71	  let contacts: Pair<Contact | null> = [detect(moveset, fighters, 0, input), detect(moveset, fighters, 1, input)];
72	
73	  // 3. Same-frame interactions.
74	  const clash = contacts[0]?.kind === "grab" && contacts[1]?.kind === "grab";
75	  if (clash) {
76	    contacts = [null, null];
77	  } else {
78	    // A grab fails against a strike that hits or is blocked on the same frame; an active hitbox that misses does not
79	    // stop it.
80	    const strikes = (contact: Contact | null) => contact !== null && contact.kind !== "grab";
81	    contacts = [
82	      contacts[0]?.kind === "grab" && strikes(contacts[1]) ? null : contacts[0],
83	      contacts[1]?.kind === "grab" && strikes(contacts[0]) ? null : contacts[1],
