105	  if (throwBreak) {
106	    for (const index of [0, 1] as const) {
107	      shift[index]! += awayFrom(fighters[index], fighters[OTHER[index]]) * moveset.fighter.throwBreakPushback;
108	    }
109	  }
110	
111	  // 4. Apply results and advance actions.
112	  const events: DuelEvent[] = [];
113	  const spent = [false, false];
114	  const next = both((index): FighterState => {
115	    const self = fighters[index];
116	    const opponent = fighters[OTHER[index]];
117	    const incoming = contacts[OTHER[index]];
118	    const outgoing = contacts[index];
119	    const own = input[index];
120	    let fighter: FighterState = { ...self, held: own.bits, buffer: own.buffer };
121	    if (throwBreak) {
122	      // Two throws on one frame, or an escape: both fighters recover apart with no damage.
123	      if (clash) events.push({ kind: "throw-clash", attacker: index, moveId: self.moveId ?? "", damage: 0 });
124	      if (escape[OTHER[index]]) events.push({ kind: "throw-escape", attacker: index, moveId: moveset.commands.throw, damage: 0 });
125	      return startTimed(fighter, "throw-break", moveset.fighter.throwBreakFrames);
126	    }
127	    if (incoming !== null) {
128	      const attacker = OTHER[index];
129	      const result = react(moveset, fighter, incoming, attacker);
130	      events.push(result.event);
131	      if (incoming.kind === "block") spent[index] = true;
132	      return result.fighter;
133	    }
134	    if (outgoing !== null) fighter = { ...fighter, moveHit: true };
135	    if (fighter.action === "thrown") {
136	      if (fighter.timer > 0) return { ...fighter, timer: fighter.timer - 1, actionFrame: fighter.actionFrame + 1 };
