179	function readInput(moveset: DuelMoveset, fighter: FighterState, raw: number): FrameInput {
180	  const bits = sanitizeDuelInput(raw);
181	  const pressed = bits & ~fighter.held;
182	  const buffer = Object.fromEntries(
183	    DUEL_BUTTONS.map((button) => [
184	      button,
185	      (pressed & DUEL_INPUT[button]) !== 0 ? moveset.rules.inputBufferFrames : Math.max(0, fighter.buffer[button] - 1),
186	    ]),
187	  ) as unknown as InputBuffer;
188	  return { bits, ...directions(bits), buffer };
