307	    fighter: {
308	      ...struck,
309	      health: Math.max(0, fighter.health - damage),
310	      combo,
311	      crouching: capped ? false : crouching,
312	      vy: move.launch > 0 ? move.launch : struck.vy,
313	    },
314	    event: { kind: "hit", attacker, moveId, damage },
